var out=[];['Light/Clean','Dark/Clean'].forEach(function(app){var p=H.page('Proto iOS '+app.split('/')[0]);p.layers.filter(l=>l.name.indexOf('Screen/ios/'+app+'/')===0).forEach(function(s){var id=s.name.split('/').slice(4).join('/');var own=['projects','projects--new','project','recent','artifacts','artifacts--detail','routines','routines--new','customize','settings','settings-account','settings-devices','settings-general','settings-appearance','settings-voice','settings-notifications','settings-connections','settings-billing','settings-privacy','settings-shortcuts','settings-about','settings--sign-out','settings-billing--plan','project--empty','artifacts--empty','project--work','artifacts--code','artifacts--share','customize--profile'];if(!own.includes(id))return;var borders=[],sizes={},overflow=[],dots=[],rings=[];function walk(l){if(l.style&&l.style.borders&&l.style.borders.some(b=>b.enabled)&&!(l.parent&&l.parent.name==='ring'))borders.push(l.name);if(l.type==='Text'&&l.name.indexOf('sf:')!==0)sizes[l.style.fontSize]=(sizes[l.style.fontSize]||0)+1;if(l.name==='dot')dots.push(l.frame.width);if(l.name==='ring')rings.push(l.frame.width);if(l.layers)l.layers.forEach(walk);}walk(s);var body=s.layers.find(l=>l.name==='body'),tab=s.layers.find(l=>l.name==='tab-bar');var end=body?Math.max.apply(null,body.layers.map(l=>l.frame.y+l.frame.height))+body.frame.y:0;out.push({id:id,app:app,frame:String(s.id),parent:p.name,width:s.frame.width,height:s.frame.height,borders:borders,sizes:sizes,dots:dots,rings:rings,bodyEnd:end,tabGap:tab?tab.frame.y-end:null});});});out.forEach(x=>console.log(JSON.stringify(x)));